alter table public.stock_movements add column if not exists transfer_no text;
create unique index if not exists stock_movements_transfer_out_no_uq on public.stock_movements(company_id,business_unit_id,transfer_no) where transfer_no is not null and adjustment_action='transfer_out';
create or replace function public.next_stock_transfer_no(p_company_id uuid,p_business_unit_id uuid) returns text language plpgsql security definer set search_path='public','pg_temp' as $$ declare v_next bigint; begin perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_business_unit_id::text||':stock_transfer_no',0)); select coalesce(max(nullif(regexp_replace(transfer_no,'[^0-9]','','g'),'')::bigint),0)+1 into v_next from public.stock_movements where company_id=p_company_id and business_unit_id=p_business_unit_id and transfer_no is not null; return 'ST-'||lpad(v_next::text,6,'0'); end $$; revoke all on function public.next_stock_transfer_no(uuid,uuid) from public,anon,authenticated;
drop function public.transfer_stock_controlled(uuid,uuid,uuid,uuid,numeric,text,text,text,uuid,text,text,uuid);
create function public.transfer_stock_controlled(p_item_id uuid,p_warehouse_id uuid,p_from_godown_id uuid,p_to_godown_id uuid,p_qty numeric,p_reason_code text,p_reason text,p_reference text,p_approved_by_employee_id uuid,p_approval_slip_path text,p_remarks text default null,p_to_warehouse_id uuid default null) returns text language plpgsql security definer set search_path='public','pg_temp' as $$ declare v_user_id uuid:=public.legacy_data_user_id(); v_company_id uuid:=public.current_company_id(); v_unit_id uuid:=public.current_business_unit_id(); v_dest_warehouse_id uuid:=coalesce(p_to_warehouse_id,p_warehouse_id); v_from_stock_id uuid; v_to_stock_id uuid; v_from_qty numeric:=0; v_to_qty numeric:=0; v_from_name text; v_to_name text; v_approver text; v_entered_by text; v_reason_code text:=lower(btrim(coalesce(p_reason_code,''))); v_reason text:=btrim(coalesce(p_reason,'')); v_reference text:=btrim(coalesce(p_reference,'')); v_slip text:=btrim(coalesce(p_approval_slip_path,'')); v_transfer_no text; begin perform public.assert_module_permission('inventory','edit'); if v_user_id is null or v_company_id is null or v_unit_id is null then raise exception 'Authentication, active company and business unit are required.'; end if; if p_item_id is null or p_warehouse_id is null or v_dest_warehouse_id is null or p_from_godown_id is null or p_to_godown_id is null then raise exception 'Item, source/destination warehouse and both godowns are required.'; end if; if p_warehouse_id=v_dest_warehouse_id and p_from_godown_id=p_to_godown_id then raise exception 'Source and destination location cannot be the same.'; end if; if p_qty is null or p_qty<=0 then raise exception 'Transfer quantity must be greater than zero.'; end if; if v_reason_code not in ('routine_transfer','stock_rebalancing','dispatch_preparation','production_requirement','space_capacity','quality_segregation','inspection_hold','other') then raise exception 'Select a valid transfer reason.'; end if; if v_reason='' or v_reference='' or p_approved_by_employee_id is null or v_slip='' then raise exception 'Reason, reference, approver and approved slip are required.'; end if; if v_reason_code='other' and nullif(btrim(coalesce(p_remarks,'')),'') is null then raise exception 'Remarks are required when reason is Other.'; end if; if split_part(v_slip,'/',1)<>v_company_id::text or not exists(select 1 from storage.objects where bucket_id='stock-transfer-approvals' and name=v_slip) then raise exception 'Valid company approval slip is required.'; end if; if not exists(select 1 from public.items where id=p_item_id and company_id=v_company_id) then raise exception 'Selected item does not belong to active company.'; end if; if not exists(select 1 from public.warehouses where id=p_warehouse_id and company_id=v_company_id) or not exists(select 1 from public.warehouses where id=v_dest_warehouse_id and company_id=v_company_id) then raise exception 'Selected warehouse does not belong to active company.'; end if; select name into v_from_name from public.godowns where id=p_from_godown_id and warehouse_id=p_warehouse_id and company_id=v_company_id; select name into v_to_name from public.godowns where id=p_to_godown_id and warehouse_id=v_dest_warehouse_id and company_id=v_company_id; if v_from_name is null or v_to_name is null then raise exception 'Source/destination godown does not belong to selected warehouse.'; end if; select name into v_approver from public.employees where id=p_approved_by_employee_id and company_id=v_company_id and is_active=true; if v_approver is null then raise exception 'Selected approver is not active.'; end if; select coalesce((select e.name from public.employees e where e.company_id=v_company_id and e.user_id=auth.uid() and e.is_active=true limit 1),auth.jwt()->>'email',auth.uid()::text) into v_entered_by; perform pg_advisory_xact_lock(hashtextextended(v_company_id::text||':'||v_unit_id::text||':'||p_item_id::text||':'||least(p_warehouse_id::text,v_dest_warehouse_id::text)||':'||greatest(p_warehouse_id::text,v_dest_warehouse_id::text),0)); select id,coalesce(quantity,0) into v_from_stock_id,v_from_qty from public.warehouse_stock where company_id=v_company_id and business_unit_id=v_unit_id and item_id=p_item_id and warehouse_id=p_warehouse_id and godown_id=p_from_godown_id limit 1 for update; if v_from_stock_id is null or p_qty>coalesce(v_from_qty,0) then raise exception 'Insufficient stock. Available: %, Required: %.',coalesce(v_from_qty,0),p_qty; end if; select id,coalesce(quantity,0) into v_to_stock_id,v_to_qty from public.warehouse_stock where company_id=v_company_id and business_unit_id=v_unit_id and item_id=p_item_id and warehouse_id=v_dest_warehouse_id and godown_id=p_to_godown_id limit 1 for update; v_to_qty:=coalesce(v_to_qty,0); v_transfer_no:=public.next_stock_transfer_no(v_company_id,v_unit_id); update public.warehouse_stock set quantity=v_from_qty-p_qty,updated_at=now(),godown=v_from_name where id=v_from_stock_id; if v_to_stock_id is null then insert into public.warehouse_stock(user_id,company_id,business_unit_id,item_id,warehouse_id,godown_id,godown,quantity,updated_at) values(v_user_id,v_company_id,v_unit_id,p_item_id,v_dest_warehouse_id,p_to_godown_id,v_to_name,p_qty,now()); else update public.warehouse_stock set quantity=v_to_qty+p_qty,updated_at=now(),godown=v_to_name where id=v_to_stock_id; end if; insert into public.stock_movements(user_id,company_id,business_unit_id,item_id,warehouse_id,godown_id,godown,type,qty,reference,reason_code,reason,remarks,approved_by_employee_id,approved_by_name,entered_by_name,approval_slip_path,source_type,previous_qty,resulting_qty,adjustment_action,created_by,transfer_no) values (v_user_id,v_company_id,v_unit_id,p_item_id,p_warehouse_id,p_from_godown_id,v_from_name,'out',p_qty,v_reference,v_reason_code,v_reason,nullif(btrim(coalesce(p_remarks,'')),''),p_approved_by_employee_id,v_approver,v_entered_by,v_slip,'warehouse_transfer',v_from_qty,v_from_qty-p_qty,'transfer_out',auth.uid(),v_transfer_no),(v_user_id,v_company_id,v_unit_id,p_item_id,v_dest_warehouse_id,p_to_godown_id,v_to_name,'in',p_qty,v_reference,v_reason_code,v_reason,nullif(btrim(coalesce(p_remarks,'')),''),p_approved_by_employee_id,v_approver,v_entered_by,v_slip,'warehouse_transfer',v_to_qty,v_to_qty+p_qty,'transfer_in',auth.uid(),v_transfer_no); return v_transfer_no; end $$; revoke execute on function public.transfer_stock_controlled(uuid,uuid,uuid,uuid,numeric,text,text,text,uuid,text,text,uuid) from public,anon; grant execute on function public.transfer_stock_controlled(uuid,uuid,uuid,uuid,numeric,text,text,text,uuid,text,text,uuid) to authenticated;
